ExecutorCompletionService<Quote> cs = new ExecutorCompletionService<>(pool);
vendors.forEach(v -> cs.submit(() -> ask(v)));
List<Quote> got = new ArrayList<>();
long deadline = System.nanoTime() + TIMEOUT_NS;
while (got.size() < vendors.size()) {
    Future<Quote> f = cs.poll(remainingNanos(deadline), NANOSECONDS);
    if (f == null) break;                 // time-out completeness condition
    got.add(f.get());
}
publish(bestOf(got));
